ed mb-0">No existen eventos con estos filtros.</p><?php endif; ?><div class="row g-2"><?php foreach ($resumenAreas as $indice => $fila): if (!(int)$fila['total_eventos']) continue; ?><div class="col-12 col-sm-6"><div class="d-flex align-items-center gap-2"><span class="rounded-circle flex-shrink-0" style="width:12px;height:12px;background:<?= $colores[$indice % count($colores)] ?>"></span><span class="small flex-grow-1"><?= htmlspecialchars($fila['area']) ?></span><strong><?= (int)$fila['total_eventos'] ?></strong></div></div><?php endforeach; ?></div></div></div></div></div></section>

